def run_monthly_client_performance_reports(run_at: str | None = None) -> dict:
    """Draft and hand off the agency's monthly paid-media reports.

    Implements the canonical rules in guidance entry "Monthly paid-media client
    performance reporting SOP". ``run_at`` is an optional ISO-8601 UTC timestamp
    for deterministic replay/testing; when omitted, the current UTC month is
    used. The function reads the authorized local API, posts exactly one drafted
    or blocked delivery attempt per returned client, never sends email, and
    returns a compact run summary. Client-local failures are converted into
    blocked deliveries; delivery POST failures are collected and raised after
    all clients have been attempted.
    """
    import json
    import logging
    from collections import defaultdict
    from datetime import datetime, timezone
    from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
    from urllib import error, parse, request

    log = logging.getLogger(__name__)
    base_url = "http://127.0.0.1:8151"

    if run_at is None:
        activation = datetime.now(timezone.utc)
    else:
        normalized = run_at.strip().replace("Z", "+00:00")
        activation = datetime.fromisoformat(normalized)
        if activation.tzinfo is None:
            activation = activation.replace(tzinfo=timezone.utc)
        else:
            activation = activation.astimezone(timezone.utc)

    def shift_month(delta: int) -> str:
        index = activation.year * 12 + activation.month - 1 + delta
        return f"{index // 12:04d}-{index % 12 + 1:02d}"

    report_month = shift_month(-1)
    prior_month = shift_month(-2)

    def api(method: str, path: str, payload=None):
        body = (
            json.dumps(payload, ensure_ascii=False).encode("utf-8")
            if payload is not None
            else None
        )
        headers = {"Accept": "application/json"}
        if body is not None:
            headers["Content-Type"] = "application/json"
        req = request.Request(
            base_url + path, data=body, method=method, headers=headers
        )
        try:
            with request.urlopen(req, timeout=20) as response:
                raw = response.read().decode("utf-8")
                return json.loads(raw) if raw else None
        except error.HTTPError as exc:
            detail = exc.read().decode("utf-8", errors="replace")[:300]
            raise RuntimeError(
                f"{method} {path} returned HTTP {exc.code}: {detail}"
            ) from exc
        except error.URLError as exc:
            raise RuntimeError(
                f"{method} {path} could not be reached: {exc.reason}"
            ) from exc
        except json.JSONDecodeError as exc:
            raise RuntimeError(f"{method} {path} returned invalid JSON") from exc

    def rows(value, endpoint: str) -> list:
        if isinstance(value, list):
            return value
        if isinstance(value, dict):
            for key in (
                "data",
                "results",
                "items",
                "clients",
                "campaigns",
                "rows",
            ):
                if isinstance(value.get(key), list):
                    return value[key]
        raise ValueError(f"{endpoint} returned an unsupported response shape")

    def decimal_value(value, field: str) -> Decimal:
        if value is None or isinstance(value, bool):
            raise ValueError(f"missing or invalid {field}")
        try:
            return Decimal(str(value))
        except (InvalidOperation, ValueError) as exc:
            raise ValueError(f"invalid numeric {field}") from exc

    def integer_cents(value, field: str) -> int:
        amount = decimal_value(value, field)
        if amount != amount.to_integral_value():
            raise ValueError(f"{field} was not integer cents")
        return int(amount)

    def money(cents: int | Decimal) -> str:
        amount = (Decimal(cents) / Decimal(100)).quantize(
            Decimal("0.01"), rounding=ROUND_HALF_UP
        )
        return f"${amount:,.2f}"

    def number(value) -> str:
        amount = Decimal(value)
        if amount == amount.to_integral_value():
            return f"{int(amount):,}"
        return f"{amount:,.2f}"

    def cpa_text(spend_cents, conversions) -> str:
        conversions = Decimal(conversions)
        if conversions <= 0:
            return "—"
        amount = (Decimal(spend_cents) / conversions / Decimal(100)).quantize(
            Decimal("0.01"), rounding=ROUND_HALF_UP
        )
        return f"${amount:,.2f}"

    def pct_text(current, previous) -> str:
        current, previous = Decimal(current), Decimal(previous)
        if previous == 0:
            return "n/a"
        return f"{(current - previous) / abs(previous) * Decimal(100):+.1f}%"

    def analytics_platform(value) -> str | None:
        source = (
            str(value or "")
            .strip()
            .lower()
            .replace("-", "_")
            .replace(" ", "_")
        )
        google = any(token in source for token in ("google", "adwords"))
        meta = any(
            token in source
            for token in ("meta", "facebook", "instagram", "fb_ads")
        )
        if google and not meta:
            return "google_ads"
        if meta and not google:
            return "meta_ads"
        return None

    def aggregate_ads(source_rows: list, platform: str, expected_month: str) -> dict:
        output = {}
        for index, row in enumerate(source_rows):
            if not isinstance(row, dict):
                raise ValueError(f"{platform} row {index} was not an object")
            campaign_id = row.get("campaign_id")
            if campaign_id is None or str(campaign_id) == "":
                raise ValueError(f"{platform} row {index} lacked campaign_id")
            if row.get("month") not in (None, expected_month):
                raise ValueError(f"{platform} returned a row for the wrong month")
            key = str(campaign_id)
            record = output.setdefault(
                key,
                {
                    "campaign_id": key,
                    "campaign": str(row.get("campaign") or key),
                    "spend_cents": 0,
                    "impressions": Decimal(0),
                    "clicks": Decimal(0),
                    "conversions": Decimal(0),
                },
            )
            record["spend_cents"] += integer_cents(
                row.get("spend_cents"), "spend_cents"
            )
            for field in ("impressions", "clicks", "conversions"):
                record[field] += decimal_value(row.get(field), field)
        return output

    def aggregate_analytics(
        source_rows: list, expected_month: str, revenue_tracked: bool
    ) -> tuple[dict, int]:
        output = defaultdict(
            lambda: {
                "sessions": Decimal(0),
                "conversions": Decimal(0),
                "revenue_cents": 0,
                "revenue_present": False,
            }
        )
        skipped = 0
        for index, row in enumerate(source_rows):
            if not isinstance(row, dict):
                raise ValueError(f"analytics row {index} was not an object")
            campaign_id = row.get("campaign_id")
            if campaign_id is None or str(campaign_id) == "":
                raise ValueError(f"analytics row {index} lacked campaign_id")
            if row.get("month") not in (None, expected_month):
                raise ValueError("analytics returned a row for the wrong month")
            platform = analytics_platform(
                row.get("source") or row.get("platform")
            )
            if platform is None:
                skipped += 1
                continue
            record = output[(str(campaign_id), platform)]
            record["sessions"] += decimal_value(
                row.get("sessions"), "analytics sessions"
            )
            record["conversions"] += decimal_value(
                row.get("conversions"), "analytics conversions"
            )
            revenue = row.get("revenue_cents", row.get("revenue"))
            if revenue_tracked and revenue is not None:
                record["revenue_cents"] += integer_cents(
                    revenue, "analytics revenue_cents"
                )
                record["revenue_present"] = True
        return dict(output), skipped

    def build_flags(current: dict, previous: dict) -> list[dict]:
        output = []
        for platform in ("google_ads", "meta_ads"):
            for campaign_id in sorted(
                set(current[platform]) | set(previous[platform])
            ):
                cur = current[platform].get(
                    campaign_id,
                    {"spend_cents": 0, "conversions": Decimal(0)},
                )
                prev = previous[platform].get(
                    campaign_id,
                    {"spend_cents": 0, "conversions": Decimal(0)},
                )
                cur_spend, prev_spend = cur["spend_cents"], prev["spend_cents"]
                cur_conv = Decimal(cur["conversions"])
                prev_conv = Decimal(prev["conversions"])

                if (
                    cur_spend >= prev_spend
                    and prev_conv > 0
                    and cur_conv * Decimal(3) < prev_conv * Decimal(2)
                ):
                    output.append(
                        {
                            "campaign_id": campaign_id,
                            "platform": platform,
                            "reason": "Spend did not decrease while conversions fell by more than one third versus the prior month.",
                        }
                    )

                if cur_conv > 0 and prev_conv > 0:
                    current_cpa = Decimal(cur_spend) / cur_conv
                    previous_cpa = Decimal(prev_spend) / prev_conv
                    if (
                        previous_cpa > 0
                        and abs(current_cpa / previous_cpa - Decimal(1))
                        > Decimal("0.40")
                    ):
                        direction = (
                            "increased"
                            if current_cpa > previous_cpa
                            else "decreased"
                        )
                        output.append(
                            {
                                "campaign_id": campaign_id,
                                "platform": platform,
                                "reason": f"Cost per conversion {direction} by more than 40% versus the prior month.",
                            }
                        )

                if cur_spend > 20000 and cur_conv == 0:
                    output.append(
                        {
                            "campaign_id": campaign_id,
                            "platform": platform,
                            "reason": "Report-month spend was over $200 with zero conversions.",
                        }
                    )
        return output

    def totals(campaigns: dict) -> dict:
        return {
            field: sum(
                (record[field] for record in campaigns.values()), Decimal(0)
            )
            for field in (
                "spend_cents",
                "impressions",
                "clicks",
                "conversions",
            )
        }

    def build_report(
        client: dict,
        current: dict,
        previous: dict,
        analytics_current: dict,
        analytics_previous: dict,
        flags: list[dict],
        skipped_analytics: int,
    ) -> str:
        client_name = str(
            client.get("name")
            or client.get("client_name")
            or client["client_id"]
        )
        revenue_tracked = bool(client.get("revenue_tracked", False))
        flagged_pairs = {
            (flag["campaign_id"], flag["platform"]) for flag in flags
        }
        lines = [
            f"# {client_name} Performance Report — {report_month}",
            "",
            f"Comparison period: {prior_month}",
            "",
            "## Flagged campaigns",
            "",
        ]
        if flags:
            for flag in flags:
                record = current[flag["platform"]].get(
                    flag["campaign_id"]
                ) or previous[flag["platform"]].get(flag["campaign_id"], {})
                lines.append(
                    f"- **{record.get('campaign', flag['campaign_id'])}** "
                    f"(`{flag['campaign_id']}`, {flag['platform']}): "
                    f"{flag['reason']}"
                )
        else:
            lines.append("No campaigns met the specified flagging thresholds.")

        lines += ["", "## Executive summary", ""]
        for platform, label in (
            ("google_ads", "Google Ads"),
            ("meta_ads", "Meta Ads"),
        ):
            current_total = totals(current[platform])
            previous_total = totals(previous[platform])
            lines.append(
                f"- **{label}:** spend {money(current_total['spend_cents'])} "
                f"({pct_text(current_total['spend_cents'], previous_total['spend_cents'])}); "
                f"clicks {number(current_total['clicks'])} "
                f"({pct_text(current_total['clicks'], previous_total['clicks'])}); "
                f"ad-platform conversions {number(current_total['conversions'])} "
                f"({pct_text(current_total['conversions'], previous_total['conversions'])})."
            )
        lines += [
            f"- **Review priority:** {len(flagged_pairs)} campaign/platform "
            f"combination(s), represented by {len(flags)} flag reason(s).",
            "",
        ]

        for platform, label in (
            ("google_ads", "Google Ads"),
            ("meta_ads", "Meta Ads"),
        ):
            revenue_header = (
                " | Analytics revenue (report / prior)"
                if revenue_tracked
                else ""
            )
            lines += [
                f"## {label} campaign comparison",
                "",
                "| Priority | Campaign | ID | Spend (report / prior) | "
                "Impressions (report / prior) | Clicks (report / prior) | "
                "Ad conversions (report / prior) | Cost/conv. (report / prior) | "
                "Analytics sessions (report / prior) | Analytics conversions "
                "(report / prior)"
                + revenue_header
                + " |",
                "|---|---|---|---:|---:|---:|---:|---:|---:|---:"
                + ("|---:" if revenue_tracked else "")
                + "|",
            ]
            campaign_ids = set(current[platform]) | set(previous[platform])
            ordered = sorted(
                campaign_ids,
                key=lambda campaign_id: (
                    (campaign_id, platform) not in flagged_pairs,
                    (
                        current[platform].get(campaign_id)
                        or previous[platform][campaign_id]
                    )["campaign"].lower(),
                    campaign_id,
                ),
            )
            if not ordered:
                lines.append(
                    "| — | No campaign rows returned | — | — | — | — | — | — | — | —"
                    + (" | —" if revenue_tracked else "")
                    + " |"
                )
            for campaign_id in ordered:
                cur = current[platform].get(
                    campaign_id,
                    {
                        "campaign": previous[platform][campaign_id]["campaign"],
                        "spend_cents": 0,
                        "impressions": 0,
                        "clicks": 0,
                        "conversions": 0,
                    },
                )
                prev = previous[platform].get(
                    campaign_id,
                    {
                        "campaign": cur["campaign"],
                        "spend_cents": 0,
                        "impressions": 0,
                        "clicks": 0,
                        "conversions": 0,
                    },
                )
                cur_a = analytics_current.get((campaign_id, platform), {})
                prev_a = analytics_previous.get((campaign_id, platform), {})
                cells = [
                    "⚑" if (campaign_id, platform) in flagged_pairs else "—",
                    str(cur.get("campaign") or prev.get("campaign") or campaign_id).replace("|", "\\|"),
                    f"`{campaign_id}`",
                    f"{money(cur['spend_cents'])} / {money(prev['spend_cents'])}",
                    f"{number(cur['impressions'])} / {number(prev['impressions'])}",
                    f"{number(cur['clicks'])} / {number(prev['clicks'])}",
                    f"{number(cur['conversions'])} / {number(prev['conversions'])}",
                    f"{cpa_text(cur['spend_cents'], cur['conversions'])} / {cpa_text(prev['spend_cents'], prev['conversions'])}",
                    f"{number(cur_a.get('sessions', 0))} / {number(prev_a.get('sessions', 0))}",
                    f"{number(cur_a.get('conversions', 0))} / {number(prev_a.get('conversions', 0))}",
                ]
                if revenue_tracked:
                    cur_revenue = (
                        money(cur_a["revenue_cents"])
                        if cur_a.get("revenue_present")
                        else "—"
                    )
                    prev_revenue = (
                        money(prev_a["revenue_cents"])
                        if prev_a.get("revenue_present")
                        else "—"
                    )
                    cells.append(f"{cur_revenue} / {prev_revenue}")
                lines.append("| " + " | ".join(cells) + " |")
            lines.append("")

        lines += [
            "## What happened",
            "",
            (
                f"Observed: {len(flags)} threshold breach(es) affected "
                f"{len(flagged_pairs)} campaign/platform combination(s)."
                if flags
                else "Observed: no campaign met any of the three specified "
                "flagging thresholds in this comparison."
            ),
        ]
        for platform, label in (
            ("google_ads", "Google Ads"),
            ("meta_ads", "Meta Ads"),
        ):
            current_total = totals(current[platform])
            previous_total = totals(previous[platform])
            lines.append(
                f"Observed: {label} spend changed from "
                f"{money(previous_total['spend_cents'])} to "
                f"{money(current_total['spend_cents'])}, while ad-platform "
                f"conversions changed from "
                f"{number(previous_total['conversions'])} to "
                f"{number(current_total['conversions'])}."
            )
        if skipped_analytics:
            lines.append(
                f"Observed: {skipped_analytics} analytics row(s) were not "
                "assigned to either ad platform because their source/platform "
                "evidence was ambiguous."
            )

        lines += [
            "",
            "## Why",
            "",
            "The supplied data establishes the metric changes, but it does not "
            "establish their causes. Plausible explanations to investigate—not "
            "conclusions—include changes in audience mix, auction conditions, "
            "creative or offer performance, landing-page behavior, tracking, or "
            "campaign configuration. Analytics figures are shown only where "
            "campaign ID and source/platform evidence support a conservative "
            "match; differences between ad-platform and analytics conversions "
            "may reflect attribution or tracking differences and should not be "
            "treated as proof of a specific cause.",
            "",
            "## What we'd change",
            "",
        ]
        if flags:
            lines.append(
                "- Review every flagged campaign before changing budgets; "
                "verify conversion tracking and recent configuration changes first."
            )
            if any("zero conversions" in flag["reason"].lower() for flag in flags):
                lines.append(
                    "- For campaigns that spent over $200 with zero conversions, "
                    "consider pausing or reducing spend until tracking, targeting, "
                    "creative, and landing-page performance have been checked."
                )
            if any("did not decrease" in flag["reason"].lower() for flag in flags):
                lines.append(
                    "- For campaigns where spend held or rose while conversions "
                    "fell sharply, inspect search terms/audiences, placements, bids, "
                    "and recent edits before reallocating budget."
                )
            if any("cost per conversion" in flag["reason"].lower() for flag in flags):
                lines.append(
                    "- Investigate large cost-per-conversion movements and preserve "
                    "beneficial decreases only after validating conversion quality "
                    "and tracking consistency."
                )
        else:
            lines.append(
                "- No threshold-triggered budget change is recommended from this "
                "report alone; continue monitoring and validate conversion quality "
                "and tracking consistency."
            )
        lines.append(
            "- Treat these as review actions, not automated changes; the dataset "
            "does not support a causal diagnosis on its own."
        )
        return "\n".join(lines).strip() + "\n"

    def draft_email(client_name: str, flags: list[dict]) -> dict:
        if flags:
            pairs = {
                (flag["campaign_id"], flag["platform"]) for flag in flags
            }
            summary = (
                f"The draft identifies {len(flags)} flag reason(s) across "
                f"{len(pairs)} campaign/platform combination(s)."
            )
        else:
            summary = "No campaigns met the specified flagging thresholds."
        return {
            "to": "user@example.com",
            "subject": f"Draft performance report for {client_name} — {report_month}",
            "body": (
                f"Hi Default User,\n\nThe {report_month} performance report for "
                f"{client_name}, compared with {prior_month}, is ready as a draft "
                f"for your review. {summary}\n\nPlease review the attached/linked "
                "draft report before any client-facing use. No email has been "
                "sent to the client.\n\nBest,\nUnify"
            ),
        }

    def blocked_delivery(client_id, client_name: str, exception: Exception) -> dict:
        reason = " ".join(
            f"required source retrieval or report generation failed: "
            f"{type(exception).__name__}: {exception}".split()
        )
        reason = reason.replace(".", "")[:400].rstrip() + "."
        return {
            "client_id": client_id,
            "month": report_month,
            "status": "blocked",
            "blocked_reason": reason,
            "flagged": [],
            "doc_markdown": "",
            "draft_email": {
                "to": "user@example.com",
                "subject": f"Blocked draft performance report for {client_name} — {report_month}",
                "body": (
                    f"Hi Default User,\n\nThe {report_month} draft performance "
                    f"report for {client_name} is blocked because "
                    f"{reason[0].lower() + reason[1:]} No report data has been "
                    "fabricated, and nothing has been sent.\n\nBest,\nUnify"
                ),
            },
        }

    log.info(
        "PHASE client_list_fetch report_month=%s prior_month=%s",
        report_month,
        prior_month,
    )
    clients = rows(api("GET", "/clients"), "/clients")
    if not all(
        isinstance(client, dict) and client.get("client_id") is not None
        for client in clients
    ):
        raise RuntimeError("GET /clients returned one or more clients without client_id")
    log.info("PHASE client_list_ready client_count=%d", len(clients))
    if not clients:
        log.info("SKIP no_clients_returned")

    summaries = []
    delivery_failures = []
    for index, client in enumerate(clients, 1):
        client_id = client["client_id"]
        client_name = str(
            client.get("name") or client.get("client_name") or client_id
        )
        encoded_id = parse.quote(str(client_id), safe="")
        log.info(
            "PHASE client_start client_id=%s client_index=%d/%d",
            client_id,
            index,
            len(clients),
        )
        try:
            current, previous = {}, {}
            for platform in ("google_ads", "meta_ads"):
                current[platform] = aggregate_ads(
                    rows(
                        api(
                            "GET",
                            f"/clients/{encoded_id}/{platform}?month={report_month}",
                        ),
                        platform,
                    ),
                    platform,
                    report_month,
                )
                previous[platform] = aggregate_ads(
                    rows(
                        api(
                            "GET",
                            f"/clients/{encoded_id}/{platform}?month={prior_month}",
                        ),
                        platform,
                    ),
                    platform,
                    prior_month,
                )

            analytics_current, skipped_current = aggregate_analytics(
                rows(
                    api(
                        "GET",
                        f"/clients/{encoded_id}/analytics?month={report_month}",
                    ),
                    "analytics",
                ),
                report_month,
                bool(client.get("revenue_tracked", False)),
            )
            analytics_previous, skipped_previous = aggregate_analytics(
                rows(
                    api(
                        "GET",
                        f"/clients/{encoded_id}/analytics?month={prior_month}",
                    ),
                    "analytics",
                ),
                prior_month,
                bool(client.get("revenue_tracked", False)),
            )
            skipped_total = skipped_current + skipped_previous
            if skipped_total:
                log.info(
                    "SKIP ambiguous_analytics_rows client_id=%s count=%d",
                    client_id,
                    skipped_total,
                )
            log.info("PHASE source_fetch_complete client_id=%s", client_id)

            flags = build_flags(current, previous)
            payload = {
                "client_id": client_id,
                "month": report_month,
                "status": "drafted",
                "blocked_reason": "",
                "flagged": flags,
                "doc_markdown": build_report(
                    client,
                    current,
                    previous,
                    analytics_current,
                    analytics_previous,
                    flags,
                    skipped_total,
                ),
                "draft_email": draft_email(client_name, flags),
            }
            log.info(
                "PHASE report_generated client_id=%s flags=%d",
                client_id,
                len(flags),
            )
        except Exception as exc:
            log.exception("SOFT_FAIL client_blocked client_id=%s", client_id)
            payload = blocked_delivery(client_id, client_name, exc)

        if set(payload) != {
            "client_id",
            "month",
            "status",
            "blocked_reason",
            "flagged",
            "doc_markdown",
            "draft_email",
        }:
            raise RuntimeError("delivery payload keys violated the exact contract")

        try:
            api("POST", "/deliveries", payload)
            log.info(
                "PHASE delivery_posted client_id=%s status=%s",
                client_id,
                payload["status"],
            )
            summaries.append(
                {
                    "client_id": client_id,
                    "client_name": client_name,
                    "status": payload["status"],
                    "flag_count": len(payload["flagged"]),
                }
            )
        except Exception as exc:
            log.exception("SOFT_FAIL delivery_post_failed client_id=%s", client_id)
            delivery_failures.append(
                {"client_id": client_id, "error": str(exc)}
            )

    if delivery_failures:
        raise RuntimeError(
            f"Delivery POST failed for {len(delivery_failures)} client(s): "
            f"{delivery_failures}"
        )

    drafted = sum(item["status"] == "drafted" for item in summaries)
    blocked = sum(item["status"] == "blocked" for item in summaries)
    log.info(
        "PHASE run_complete clients=%d drafted=%d blocked=%d",
        len(summaries),
        drafted,
        blocked,
    )
    return {
        "report_month": report_month,
        "prior_month": prior_month,
        "clients": summaries,
    }
